import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-07-02","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-07-02","date":"2025-07-02T00:00:00.000Z","updated":"2025-07-09T00:00:00.000Z","tags":["Ceph","RGW","Object Storage","DDUP","API"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-02.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-02.md","lastUpdated":1780460162000}'),n={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-02.md"};function a(p,e,r,_,s,c){return i(),l("div",null,[...e[0]||(e[0]=[o("<p>本次Ceph RGW重构会议于2025年7月2日举行，主要讨论了以下几个议题：</p><ol><li><p><strong>RGW对象去重（DDUP）优化</strong>：</p><ul><li>会议讨论了当前DDUP实现的局限性，即仅支持对RGW对象的尾部进行去重，而头部由于包含元数据无法去重。</li><li>提出了优化方案，包括多部分上传模式、拆分头部对象以及修改Manifest来实现完整对象去重。</li><li>讨论了性能权衡和兼容性风险，并决定首先发布当前部分去重方案，收集用户反馈后再决定是否优化头部处理。</li></ul></li><li><p><strong>S3 Control API冲突问题</strong>：</p><ul><li>讨论了S3 Control API与标准S3 API共享同一端点可能导致的命名冲突问题。</li><li>提出了解决方案，包括DNS路由分离、复用虚拟主机逻辑以及独立端点。</li><li>会议倾向于基于DNS的解决方案，并决定继续研究虚拟主机代码改造，确保兼容性。</li></ul></li><li><p><strong>Bucket Notification Valgrind内存泄漏问题</strong>：</p><ul><li>报告了Bucket Notification测试中出现的Valgrind内存泄漏问题。</li><li>分析了泄漏现象和排查方向，并决定逐步定位泄漏源，协助审查相关代码。</li></ul></li></ol><p>会议还总结了行动计划，包括联系Yehuda了解manifest修改可行性、研究虚拟主机代码改造、逐步定位泄漏源等。</p><p>[改进点]</p><ul><li>确保保留所有计算机科学/ceph相关领域的英文原文关键词。</li><li>优化了总结的结构，使其更清晰地反映了会议的关键细节和讨论的主要议题。</li><li>确保了总结的准确性和完整性，避免了可能的错误、误解或遗漏的重要信息。</li></ul>",5)])])}const f=t(n,[["render",a]]);export{d as __pageData,f as default};
